<template>
  <div class="limit-buy">
    <div class="time-box" ref="timeList">
        <div class="list-wrapper">
          <div class="list">
            <div class="item" :class="[{'other': item.status != 3}, {'active': detail.activeId == item.activity_id}]" v-for="(item, index) in detail.activity_list" :key="index" @click="changeLimitList(index)">
              <div class="time">{{item.title}}</div>
              <div class="txt" v-show="item.status == 1">已开抢</div>
              <div class="txt" v-show="item.status == 2">即将开始</div>
              <div class="txt" v-show="item.status == 3">抢购中</div>
            </div>
          </div>
        </div>
      </div>
    <div class="count-down" v-show="detail.activeId == detail.default_activity_id">
      <span class="desc">{{detail.tips}}</span>
      <span class="time">{{activityTime.hours}}</span>
      <span class="icon">:</span>
      <span class="time">{{activityTime.min}}</span>
      <span class="icon">:</span>
      <span class="time">{{activityTime.sec}}</span>
    </div>
    <div class="goods-list mescroll" ref="pageMScroll">
      <div class="list">
        <div class="item" v-for="item in goodsList" :key="item.goods_id" @click="checkGoodsDetail(item.goods_id)">
          <div class="img-box">
            <img class="img" :src="item.image" alt="">
            <img class="icon" v-if="item.labels && item.labels.type == 1" :src="item.labels.image" alt="">
            <span class="icon txt-icon main-color-bg" v-if="item.labels && item.labels.type == 0" :style="{background:'-webkit-linear-gradient(top,'+ item.labels.color +','+ item.labels.color2 +') !important'}">{{item.labels.name}}</span>
          </div>
          <div class="desc-box">
            <div class="name">{{ item.limit_buy == 0 ? '' : '【限购'+item.limit_buy+'份】' }}{{item.name}}</div>
            <div class="total-buy">累计{{item.sell_count}}件</div>
            <div class="price-box">
              <div>
                <span class="now now-icon main-color-font">¥</span>
                <span class="now main-color-font">{{item.price}}</span>
                <span class="old">¥{{item.old_price}}</span>
              </div>
              <AddToCart v-if="detail.activity_list[activeIndex].status == 3 && item.stock_status == 0 && item.is_no_start == 0 && item.limit_buy_status == 0" type="big" :goodsId="item.goods_id"/>
              <div class="start-tip" v-if="detail.activity_list[activeIndex].status == 2">即将开始</div>
              <div class="start-tip black" v-if="detail.activity_list[activeIndex].status == 1">已结束</div>
            </div>
          </div>
          <div class="close-buy" v-if="item.stock_status == 1 || item.is_no_start == 1">
            <div class="icon-box">
              <div class="icon" v-if=" item.stock_status == 1 ">已抢光</div>
              <div class="icon" v-else-if=" item.is_no_start == 1">未开始</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import MeScroll from 'mescroll.js'
import AddToCart from '../../components/AddToCart/AddToCart'
export default {
  name: 'LimitBuy',
  data () {
    return {
      detail: '',
      goodsList: [],
      leader_id: '',
      activity_id: '',
      pageScroll: '',
      page: 1,
      isComplete: false,
      timer: '',
      activityTime: {},
      activeIndex: -1
    }
  },
  created () {
    this.leader_id = this.$util.storage.get('leader_id')
    this.activity_id = this.$global.activityId
    this.getLimitDetail()
  },
  methods: {
    // 查看商品详情
    checkGoodsDetail (id) {
      this.$router.push({ path: '/goods', query: { goodsId: id, leaderId: this.leader_id } })
    },
    // 切换限时活动商品列表
    async changeLimitList (index) {
      let id = this.detail.activity_list[index].activity_id
      if (id == this.detail.activeId) {
        return
      }
      this.activeIndex = index
      this.detail.activeId = id
      this.page = 1
      this.isComplete = false
      this.getGoodsList()
    },
    async getGoodsList () {
      let param = {
        leader_id: this.leader_id,
        activity_id: this.detail.activeId,
        page: this.page
      }
      let res = await this.$api.getActivityGoods(param)
      if (!res) return
      if (this.page == 1) {
        this.goodsList = []
      }
      this.goodsList = this.goodsList.concat(res)
      if (res.length < 20) {
        this.isComplete = true
      } else {
        this.page++
      }
      this.pageScroll.endSuccess(res.length, !this.isComplete)
    },
    async getLimitDetail () {
      let param = {
        leader_id: this.leader_id,
        activity_id: this.activity_id
      }
      let res = await this.$api.getLimitTimeDetail(param)
      if (!res) return
      if (this.timer) {
        clearTimeout(this.timer)
      }
      if (res.count_down > 0) {
        this.countDown(res.count_down)
      }

      res.activeId = res.default_activity_id
      let defaultId = ''
      for (let i = 0; i < res.activity_list.length; i++) {
        if (res.activity_list[i].status == 3) {
          defaultId = res.activity_list[i].activity_id
        }
        if (res.activity_list[i].activity_id == res.default_activity_id) {
          this.activeIndex = i
        }
      }
      res.default_activity_id = defaultId
      this.detail = res
      if (document.getElementById('skeleton')) {
        document.getElementById('skeleton').remove()
      }
      this.getGoodsList()
      if (!this.pageScroll) {
        this.initialScroll()
      }
    },
    // 限时抢购倒计时
    countDown: function (s) {
      if (s < 0) {
        this.getLimitDetail()
        return
      }
      let _this = this
      this.activityTime = this.$util.timestampToTime(s)
      this.timer = setTimeout(() => {
        s--
        _this.countDown(s)
      }, 1000)
    },
    // 初始化滚动插件
    initialScroll () {
      let _this = this
      this.$nextTick(function () {
        this.pageScroll = new MeScroll(this.$refs.pageMScroll, {
          down: {
            isLock: true
          },
          up: {
            auto: false,
            callback: _this.getGoodsList,
            lazyLoad: {
              use: true
            },
            htmlNodata: '<p class="upwarp-nodata">已经到底了...</p>',
            noMoreSize: 10
          }
        })
      })
    }
  },
  components: {
    AddToCart
  }
}
</script>

<style lang="stylus" scoped>
.limit-buy
  flexbox()
  flex-direction column
  .time-box
    padding 10px 0
    overflow-x auto
    overflow-y hidden
    .list-wrapper
      display inline-block
      .list
        flexbox()
        align-items center
        margin-right 30px
        .item
          margin-left 15px
          border-radius 3px
          padding 3px 5px
          line-height 1.3
          font-size 10px
          text-align center
          .time
            font-size 16px
            font-weight bold
          &.other
            color #999999
          &.active
            padding 3px 14px
            background $color-main
            color #fff
            box-shadow 0 1px 4px 1px #ddd
  .count-down
    text-align center
    box-shadow 0 2px 4px #ddd
    padding 15px 0
    .desc
      padding-right 5px
    .time
      background #000
      color #fff
      border-radius 4px
      padding 1px 3px
    .icon
      padding 0 4px
  .goods-list
    flex-grow 1
    .list
      padding 0 15px 20px
      .item
        width 100%
        flexbox()
        padding 15px 0
        border-bottom 1PX solid #efefef
        position relative
        &:last-child
          border-bottom none
        .img-box
          width 100px
          height 100px
          overflow hidden
          flex-shrink 0
          position relative
          .img
            width 100%
            height 100%
            object-fit cover
          .icon
            position absolute
            top 0
            left 0
            width 30px
            background $color-main
            &.txt-icon
              height 30px
              color #fff
              line-height 30px
              font-size 12px
              text-align center
              overflow hidden
        .desc-box
          padding-left 10px
          flex-grow 1
          line-height 1.2
          position relative
          .name
            font-size 16px
            ellipsis(2)
            max-height 38px
          .total-buy
            margin 3px 0 5px
            color #999
          .group-buy
            font-size 10px
            background $color-main
            color #fff
            display inline-block
            padding 2px 8px
            border-radius 15px
          .price-box
            position absolute
            bottom -5px
            left 10px
            right 0px
            flexbox()
            justify-content space-between
            align-items center
            line-height 1.3
            .now
              font-size 18px
              font-weight bold
              color $color-main
              margin-right 5px
            .now-icon
              margin-right 0
              font-size 12px
            .old
              color #999999
              text-decoration line-through
            .num
              font-size 12px
              color #999999
            .start-tip
              color #bbb
              border 1PX solid #e5e5e5
              border-radius 2px
              padding 2px 5px
              &.black
                color #333
        .close-buy
          position absolute
          top 0
          left 0
          right 0
          bottom 0
          background rgba(255, 255, 255, .4)
          padding 15px 0
          .icon-box
            width 60px
            height 60px
            padding 20px
            position relative
            .icon
              width 100%
              height 100%
              background rgba(0, 0, 0, .5)
              color #fff
              border-radius 50%
              flexbox()
              justify-content center
              align-items center
              font-size 14px
</style>
